import { atom, read, update } from 'claude-code'
import type { Register } from 'claude-code'

import type { Character, Clip, Connector, Routine, SessionRow, Tab, Usage } from '../types'

const PANE = 'muse-avatar'
const FRAMES = 77
const FRAME = 92
const CLIP_MS = 8000
const MAX_SESSIONS = 18
// The tab body's height in lines, the same on every tab: one two-line row a session.
// It keeps the meters at one place and the pane short enough not to scroll.
const BODY_ROWS = MAX_SESSIONS * 2
const activity = atom({ plugin: 'muse-avatar', key: 'activity' } as const, null)
// The clip on show. It changes a few times a turn; the frames themselves play
// inside the Svg, so no site is redrawn at the frame rate and Buttons keep still.
const mood = atom({ plugin: 'muse-avatar', key: 'mood' } as const, 'idle')
const isPaneUp = atom({ plugin: 'muse-avatar', key: 'isPaneUp' } as const, false)
const tab = atom({ plugin: 'muse-avatar', key: 'tab' } as const, 'activity')
const sessions = atom({ plugin: 'muse-avatar', key: 'sessions' } as const, [])
const connectors = atom({ plugin: 'muse-avatar', key: 'connectors' } as const, null)
const routines = atom({ plugin: 'muse-avatar', key: 'routines' } as const, [])
const character = atom({ plugin: 'muse-avatar', key: 'character' } as const, { vibe: '', files: [] })
const usage = atom({ plugin: 'muse-avatar', key: 'usage' } as const, {})

const TABS: { id: Tab; icon: string; title: string }[] = [
  { id: 'activity', icon: '☰', title: 'Sessions' },
  { id: 'connectors', icon: '⌁', title: 'Connectors' },
  { id: 'routines', icon: '◷', title: 'Routines' },
  { id: 'character', icon: '◉', title: 'Character' },
]

// Newest first, one line per session file: project folder, title, last use,
// with a tab between.
// No double quote in it, so the argument survives the Windows command line.
const LIST_SESSIONS =
  "Get-ChildItem ($env:USERPROFILE + '\\.claude\\projects\\*\\*.jsonl') | Sort-Object LastWriteTime -Descending | " +
  "ForEach-Object { $m = Select-String -LiteralPath $_.FullName -Pattern 'customTitle\\W{3}([^\\x22]*)' | Select-Object -Last 1; " +
  `if ($m) { $_.Directory.Name + [char]9 + $m.Matches[0].Groups[1].Value + [char]9 + $_.LastWriteTime.ToString('MMM d, h:mm tt') } }`
// Ctrl+B to the focused window: the desktop app's shortcut for its left sidebar.
const TOGGLE_SIDEBAR = "(New-Object -ComObject WScript.Shell).SendKeys('^b')"

const clip = (text: string, max: number): string => {
  const flat = text.replace(/\s+/g, ' ').trim()

  return flat.length > max ? `${flat.slice(0, max - 1)}…` : flat
}

// The listing as rows, newest first: the drive prefix off the folder name, and
// a title once per project (a routine writes one session file per run).
export const parseSessions = (stdout: string): SessionRow[] => {
  const rows: SessionRow[] = []
  const seen = new Set<string>()

  for (const line of stdout.split(/\r?\n/)) {
    const [folder, title, when = ''] = line.split('\t')
    if (!folder || !title) {
      continue
    }
    const group = folder.replace(/^[A-Za-z]--/, '')
    if (seen.has(`${group}\t${title}`) || rows.length >= MAX_SESSIONS) {
      continue
    }
    seen.add(`${group}\t${title}`)
    rows.push({ group, title, when: when.trim() })
  }

  return rows
}

// `claude mcp list` as rows: `<name>: <target> - <mark> <state>` a server.
export const parseConnectors = (stdout: string): Connector[] => {
  const rows: Connector[] = []
  for (const line of stdout.split(/\r?\n/)) {
    const at = line.indexOf(': ')
    const dash = line.lastIndexOf(' - ')
    if (at < 1 || dash < at) {
      continue
    }
    const state = line.slice(dash + 3)
    const status = /Failed|error/i.test(state) ? 'down' : /Connected/i.test(state) ? 'ok' : 'auth'
    rows.push({ name: line.slice(0, at).replace(/^claude\.ai /, ''), status })
  }

  return rows
}

// The `name` and `description` of a routine's SKILL.md front matter.
export const parseRoutine = (folder: string, text: string): Routine => {
  const field = (key: string): string => new RegExp(`^${key}:\\s*(.+)$`, 'm').exec(text)?.[1]?.trim() ?? ''

  return { name: field('name') || folder, description: field('description') }
}

// The first line of prose in a CLAUDE.md: not a heading, not a list item.
export const vibeOf = (text: string): string =>
  clip(text.split(/\r?\n/).find(line => /^[A-Za-z*"]/.test(line.trim())) ?? '', 150)

// Circular crop of the clip's sprite strip. The strip plays inside the Svg
// (SMIL; the Svg is drawn as an image, where a data: picture is allowed and
// the sandboxed frame of `isInteractive` shows none): level up once, the other clips in a loop.
export const portraitSvg = (sheet: string, now: Clip, isBusy: boolean): string => {
  if (sheet === '') {
    // No frame file for this clip (see scripts/build-frames.sh): a plain mark.
    return `<svg xmlns="http://www.w3.org/2000/svg" viewBox="4 4 112 112" width="112" height="112">
<circle cx="60" cy="60" r="52" fill="#2c2c2e"/>
<text x="60" y="74" text-anchor="middle" fill="#e5e5ea" font-family="Segoe UI, sans-serif" font-weight="700" font-size="40">P</text>
<circle cx="60" cy="60" r="55" fill="none" stroke="${isBusy ? '#7bd88f' : '#3a3a3c'}" stroke-width="2.5"/>
</svg>`
  }
  const xs = Array.from({ length: FRAMES }, (_, i) => -i * FRAME).join(';')
  const repeat = now === 'levelup' ? 'repeatCount="1" fill="freeze"' : 'repeatCount="indefinite"'

  return `<svg xmlns="http://www.w3.org/2000/svg" viewBox="4 4 112 112" width="112" height="112">
<defs><clipPath id="c"><circle cx="60" cy="60" r="52"/></clipPath></defs>
<circle cx="60" cy="60" r="52" fill="#ffffff"/>
<g clip-path="url(#c)"><svg x="6" y="6" width="108" height="108" viewBox="0 0 ${FRAME} ${FRAME}">
<image x="0" y="0" width="${FRAMES * FRAME}" height="${FRAME}" href="data:image/jpeg;base64,${sheet}"><animate attributeName="x" values="${xs}" calcMode="discrete" dur="${CLIP_MS}ms" ${repeat}/></image>
</svg></g>
<circle cx="60" cy="60" r="55" fill="none" stroke="${isBusy ? '#7bd88f' : '#3a3a3c'}" stroke-width="2.5"/>
</svg>`
}

// The context map: one bar a meter, green to amber to red as it fills.
export const metersSvg = (now: Usage): string => {
  const meters: [string, number | undefined][] = [
    ['Context', now.context],
    ['5-hour', now.fiveHour],
    ['Weekly', now.week],
  ]
  const rows = meters
    .map(([label, value], i) => {
      const y = i * 16
      const pct = Math.max(0, Math.min(100, value ?? 0))
      const color = pct >= 85 ? '#ef5350' : pct >= 60 ? '#f5b041' : '#7bd88f'
      const text = value === undefined ? '–' : `${Math.round(value)}%`

      return `<text x="0" y="${y + 9}" fill="#9a9a9e" font-family="Segoe UI, sans-serif" font-size="10.5">${label}</text>
<rect x="56" y="${y + 2}" width="164" height="6" rx="3" fill="#8a8a8e" fill-opacity="0.25"/>
<rect x="56" y="${y + 2}" width="${(164 * pct) / 100}" height="6" rx="3" fill="${color}"/>
<text x="260" y="${y + 9}" text-anchor="end" fill="#9a9a9e" font-family="Consolas, monospace" font-size="10.5">${text}</text>`
    })
    .join('\n')

  return `<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 260 44" width="260" height="44">${rows}</svg>`
}

const sheets: Partial<Record<string, string>> = {}
let home: string | null = null
let cwd: string | null = null

async function asset($: any, name: string): Promise<string> {
  const file = `${$.plugin.root}/assets/${name}.txt`

  return (sheets[name] ??= (await $.fs.exists(file)) ? (await $.fs.read(file)).trim() : '')
}

async function dirs($: any) {
  home ??= (await $.process.run(['cmd', '/c', 'echo %USERPROFILE%'])).stdout.trim()
  cwd ??= (await $.process.run(['cmd', '/c', 'cd'])).stdout.trim()

  return { home: home as string, cwd: cwd as string }
}

async function show($: any, next: Clip) {
  await update($, mood, () => next)
}

// Level up plays once: when the clip is over the avatar goes back to idle,
// unless another clip took its place meanwhile.
function settle($: any) {
  $.clock.after(CLIP_MS, () => void update($, mood, (m: Clip) => (m === 'levelup' ? 'idle' : m)))
}

// Opens the pane and records whether a surface shows it: the mini avatar is
// drawn only while the pane is not up.
async function openPane($: any) {
  try {
    const opened = await $.ui.open({ id: PANE, title: 'Po' })
    await update($, isPaneUp, () => opened.isPlaced)
    if (!opened.isPlaced) {
      $.ui.toast(`Po pane is not shown: ${opened.reason}`)
    }
  } catch (error) {
    $.ui.toast(`Could not open the Po pane: ${String(error)}`)
  }
}

// The mini avatar's press: the pane opens and the left sidebar toggles.
async function summon($: any) {
  await openPane($)
  try {
    await $.process.run(['powershell', '-NoProfile', '-Command', TOGGLE_SIDEBAR])
  } catch (error) {
    $.ui.toast(`Could not toggle the sidebar: ${String(error)}`)
  }
}

async function loadSessions($: any) {
  try {
    const ran = await $.process.run(['powershell', '-NoProfile', '-Command', LIST_SESSIONS], { timeoutMs: 60000 })
    const rows = parseSessions(ran.stdout)
    await update($, sessions, () => rows)
  } catch (error) {
    $.ui.toast(`Could not list the sessions: ${String(error)}`)
  }
}

async function loadConnectors($: any) {
  try {
    const ran = await $.process.run(['cmd', '/c', 'claude', 'mcp', 'list'], { timeoutMs: 90000 })
    const rows = parseConnectors(ran.stdout)
    await update($, connectors, () => rows)
  } catch (error) {
    await update($, connectors, () => [])
    $.ui.toast(`Could not list the connectors: ${String(error)}`)
  }
}

async function loadRoutines($: any) {
  try {
    const root = `${(await dirs($)).home}\\.claude\\scheduled-tasks`
    const rows: Routine[] = []
    for (const entry of (await $.fs.exists(root)) ? await $.fs.list(root) : []) {
      const file = `${root}\\${entry.name}\\SKILL.md`
      if (entry.kind === 'dir' && (await $.fs.exists(file))) {
        rows.push(parseRoutine(entry.name, await $.fs.read(file)))
      }
    }
    await update($, routines, () => rows)
  } catch (error) {
    $.ui.toast(`Could not list the routines: ${String(error)}`)
  }
}

async function loadCharacter($: any) {
  try {
    const d = await dirs($)
    const soul = `${d.home}\\.claude\\CLAUDE.md`
    const local = `${d.cwd}\\CLAUDE.md`
    const memory = `${d.home}\\.claude\\projects\\${d.cwd.replace(/[:\\/]/g, '-')}\\memory`
    const files = [{ label: 'SOUL · global CLAUDE.md', path: soul }]
    files.push({ label: 'PROJECT · local CLAUDE.md', path: local })
    for (const entry of (await $.fs.exists(memory)) ? await $.fs.list(memory) : []) {
      if (entry.kind === 'file' && entry.name.endsWith('.md')) {
        files.push({ label: `MEMORY · ${entry.name}`, path: `${memory}\\${entry.name}` })
      }
    }
    const vibe = (await $.fs.exists(soul)) ? vibeOf(await $.fs.read(soul)) : ''
    const now: Character = { vibe, files }
    await update($, character, () => now)
  } catch (error) {
    $.ui.toast(`Could not read the character files: ${String(error)}`)
  }
}

async function measure($: any, e: any) {
  const window = (kind: string): number | undefined =>
    e.rateLimits.find((one: { kind: string }) => one.kind === kind)?.percentUsed
  const now: Usage = {
    context: e.context.percent,
    fiveHour: window('five_hour'),
    week: window('seven_day'),
    usd: e.cost?.usd,
  }
  await update($, usage, () => now)
}

async function loadAll($: any) {
  await Promise.all([loadSessions($), loadRoutines($), loadCharacter($)])
  await measure($, await $.session.usage())
  await loadConnectors($)
}

async function pick($: any, next: Tab) {
  await update($, tab, () => next)
  if (next === 'connectors') {
    await loadConnectors($)
  }
}

async function openFile($: any, path: string) {
  try {
    const code = await $.process.run(['cmd', '/c', 'where', 'code'])
    await $.process.run(code.exitCode === 0 ? ['cmd', '/c', 'code', path] : ['notepad', path])
  } catch (error) {
    $.ui.toast(`Could not open it: ${String(error)}`)
  }
}

async function editLocal($: any) {
  await openFile($, `${(await dirs($)).cwd}\\CLAUDE.md`)
}

export const register: Register = on => {
  on('session.start', async ($, e, next) => {
    await $.command.register({ name: 'avatar', description: 'Show the Po avatar pane' })
    // A reload ends the module's timers, the one that ends level up included,
    // while the state stays: start from idle, not from a clip left frozen.
    await update($, activity, () => null)
    await show($, 'idle')
    void openPane($)
    void loadAll($)

    return next(e)
  })

  on('command.run', { command: 'avatar' }, async $ => {
    await openPane($)
    void loadAll($)

    return { text: 'Po pane opened.' }
  })

  on('prompt.submit', async ($, e, next) => {
    await update($, activity, () => 'Thinking')
    await show($, 'working')

    return next(e)
  })

  on('tool.call', async ($, e, next) => {
    await update($, activity, () => `Running ${e.tool}`)
    await show($, 'making')
    const ran = await next(e)
    await update($, activity, () => 'Thinking')
    await show($, 'working')

    return ran
  })

  on('turn.complete', async ($, e, next) => {
    if (e.agentId !== undefined) {
      return next(e)
    }
    await update($, activity, () => null)
    await show($, e.isAborted ? 'idle' : 'levelup')
    settle($)
    void loadSessions($)

    return next(e)
  })

  on('session.measure', async ($, e, next) => {
    await measure($, e)

    return next(e)
  })

  // The pane closed, by the person's mark or by a call: the mini avatar returns.
  on('ui.close', { id: PANE }, async ($, e, next) => {
    const closed = await next(e)
    await update($, isPaneUp, () => false)

    return closed
  })

  // The band: the edit button, and the mini avatar while the pane is not up. It
  // is redrawn only when the clip changes, so its Buttons keep still.
  on('ui.render', { component: 'AbovePrompt' }, async ($, e, next) => {
    if (e.props.hasSurvey || e.surface === 'terminal') {
      return next(e)
    }
    const { Box, Svg, Button } = $.ui.resolve(e) as any
    const now = await read($, mood)
    const isBusy = (await read($, activity)) !== null
    const isUp = await read($, isPaneUp)

    return (
      <Box flexDirection="row" justifyContent="flex-end" alignItems="flex-end" gap={2} width="100%">
        <Button key="local" label="✎ Edit local CLAUDE.md" onPress={() => editLocal($)} />
        {!isUp && (
          <Box flexDirection="column" alignItems="center">
            <Svg
              key="mini"
              source={portraitSvg(await asset($, now), now, isBusy)}
              alt={`Po, ${now}`}
              width={48}
              height={48}
            />
            <Button key="open-po" label="Po" onPress={() => summon($)} />
          </Box>
        )}
      </Box>
    )
  })

  on('ui.render', { component: 'Pane', requestId: PANE }, async ($, e) => {
    const { Box, Text, Svg, Button } = $.ui.resolve(e) as any
    const doing = await read($, activity)
    const isBusy = doing !== null

    if (e.surface === 'terminal') {
      return (
        <Box flexDirection="column" alignItems="center">
          <Text bold>Po</Text>
          <Text dimColor>{doing ?? 'Connected'}</Text>
        </Box>
      )
    }

    const now = await read($, mood)
    const shown = await read($, tab)
    const meters = await read($, usage)
    // The lines left for the tab's body, so the pane never has to scroll.
    const room = BODY_ROWS
    const heading = TABS.find(one => one.id === shown)?.title ?? ''

    let body
    if (shown === 'activity') {
      const rows = (await read($, sessions)).slice(0, MAX_SESSIONS)
      body = (
        <Box flexDirection="column">
          {rows.length === 0 && <Text dimColor>No sessions found yet.</Text>}
          {rows.map(row => (
            <Box flexDirection="column">
              <Text bold wrap="truncate-end">
                {row.title}
              </Text>
              <Text dimColor wrap="truncate-end">
                {row.group}
                {row.when === '' ? '' : ` · ${row.when}`}
              </Text>
            </Box>
          ))}
        </Box>
      )
    } else if (shown === 'connectors') {
      const list = await read($, connectors)
      const dot = { ok: 'green', auth: 'yellow', down: 'red' } as const
      const word = { ok: 'connected', auth: 'needs sign-in', down: 'failed' } as const
      body = (
        <Box flexDirection="column">
          {list === null && <Text dimColor>Checking the connectors…</Text>}
          {list !== null && list.length === 0 && <Text dimColor>No connectors found.</Text>}
          {(list ?? []).slice(0, room).map(one => (
            <Text wrap="truncate-end">
              <Text color={dot[one.status]}>● </Text>
              {one.name}
              <Text dimColor> · {word[one.status]}</Text>
            </Text>
          ))}
        </Box>
      )
    } else if (shown === 'routines') {
      const list = await read($, routines)
      body = (
        <Box flexDirection="column">
          {list.length === 0 && <Text dimColor>No routines found.</Text>}
          {list.slice(0, Math.floor(room / 2)).map(one => (
            <Box flexDirection="column">
              <Text wrap="truncate-end">
                <Text dimColor>◷ </Text>
                {one.name}
              </Text>
              <Text dimColor wrap="truncate-end">
                {'  '}
                {one.description}
              </Text>
            </Box>
          ))}
        </Box>
      )
    } else {
      const who = await read($, character)
      body = (
        <Box flexDirection="column">
          <Text dimColor>VIBE</Text>
          <Text wrap="wrap">{who.vibe || 'No global CLAUDE.md found.'}</Text>
          {who.files.slice(0, Math.max(2, Math.floor((room - 6) / 2))).map((file, i) => (
            <Button key={`file:${i}`} label={`✎ ${file.label}`} onPress={() => openFile($, file.path)} />
          ))}
        </Box>
      )
    }

    return (
      <Box flexDirection="column" alignItems="center" overflow="hidden" height="100%">
        <Svg
          key="po"
          source={portraitSvg(await asset($, now), now, isBusy)}
          alt={`Po, ${now}`}
          width={112}
          height={112}
        />
        <Text>
          <Text bold>Po </Text>
          <Text color={isBusy ? 'yellow' : 'green'}>● </Text>
          <Text dimColor={!isBusy}>{isBusy ? doing : 'Connected'}</Text>
        </Text>

        <Box flexDirection="row" justifyContent="space-between" width="100%" paddingX={1}>
          {TABS.map(one => (
            <Button
              key={`tab:${one.id}`}
              label={` ${one.icon} `}
              variant={one.id === shown ? 'primary' : 'secondary'}
              onPress={() => pick($, one.id)}
            />
          ))}
        </Box>

        <Box flexDirection="column" width="100%" paddingX={1} overflow="hidden" flexGrow={1} flexShrink={1}>
          <Box flexDirection="row" justifyContent="space-between">
            <Text bold>{heading}</Text>
            {meters.usd !== undefined && <Text dimColor>${meters.usd.toFixed(2)} this session</Text>}
          </Box>
          <Box flexDirection="column" minHeight={BODY_ROWS} height={BODY_ROWS} overflow="hidden">
            {body}
          </Box>
        </Box>

        <Svg key="meters" source={metersSvg(meters)} alt="Context and usage meters" width={260} height={44} />
      </Box>
    )
  })
}

