export type Activity = string | null
export type Clip = 'idle' | 'working' | 'making' | 'levelup'
export type Tab = 'activity' | 'connectors' | 'routines' | 'character'
export type SessionRow = { group: string; title: string; when: string }
export type Connector = { name: string; status: 'ok' | 'auth' | 'down' }
export type Routine = { name: string; description: string }
export type Character = { vibe: string; files: { label: string; path: string }[] }
export type Usage = { context?: number; fiveHour?: number; week?: number; usd?: number }

declare module 'claude-code' {
  interface PluginState {
    'muse-avatar': {
      activity: Activity
      mood: Clip
      isPaneUp: boolean
      tab: Tab
      sessions: SessionRow[]
      connectors: Connector[] | null
      routines: Routine[]
      character: Character
      usage: Usage
    }
  }
}
